//! JSON forms of the protobuf types that have none of their own, for the API schemas (`#[serde(with = "...")]`):
//! `bytes` is base64 (RFC 4648, padded; unpadded is accepted when reading) and `timestamp` is RFC 3339, in UTC when
//! written (`2026-11-14T09:30:00Z`), with any offset accepted when read.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use base64::{
    Engine,
    alphabet::STANDARD as ALPHABET,
    engine::{DecodePaddingMode, GeneralPurpose, GeneralPurposeConfig},
};
use chrono::{DateTime, SecondsFormat};
use prost_types::Timestamp;
use serde::{Deserialize, Deserializer, Serialize, Serializer};

const BASE64: GeneralPurpose = GeneralPurpose::new(
    &ALPHABET,
    GeneralPurposeConfig::new().with_decode_padding_mode(DecodePaddingMode::Indifferent),
);

fn encode(bytes: &[u8]) -> String {
    BASE64.encode(bytes)
}

fn decode<E: serde::de::Error>(text: &str) -> Result<Vec<u8>, E> {
    BASE64
        .decode(text.trim())
        .map_err(|e| E::custom(format!("not base64: {e}")))
}

fn format_timestamp<E: serde::ser::Error>(ts: &Timestamp) -> Result<String, E> {
    DateTime::from_timestamp(ts.seconds, ts.nanos.max(0) as u32)
        .map(|t| t.to_rfc3339_opts(SecondsFormat::AutoSi, true))
        .ok_or_else(|| E::custom("timestamp out of range"))
}

fn parse_timestamp<E: serde::de::Error>(text: &str) -> Result<Timestamp, E> {
    let t = DateTime::parse_from_rfc3339(text.trim()).map_err(|e| {
        E::custom(format!(
            "not an RFC 3339 timestamp (2026-11-14T09:30:00Z): {e}"
        ))
    })?;
    Ok(Timestamp {
        seconds: t.timestamp(),
        nanos: t.timestamp_subsec_nanos() as i32,
    })
}

/// `bytes` -> base64 text.
pub mod bytes {
    use super::*;

    pub fn serialize<S: Serializer>(value: &[u8], s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&encode(value))
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<u8>, D::Error> {
        decode(&String::deserialize(d)?)
    }
}

/// `optional bytes` -> base64 text or `null`.
pub mod bytes_opt {
    use super::*;

    pub fn serialize<S: Serializer>(value: &Option<Vec<u8>>, s: S) -> Result<S::Ok, S::Error> {
        value.as_deref().map(encode).serialize(s)
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Option<Vec<u8>>, D::Error> {
        Option::<String>::deserialize(d)?
            .map(|t| decode(&t))
            .transpose()
    }
}

/// `repeated bytes` -> a list of base64 texts.
pub mod bytes_list {
    use super::*;

    pub fn serialize<S: Serializer>(value: &[Vec<u8>], s: S) -> Result<S::Ok, S::Error> {
        value
            .iter()
            .map(|b| encode(b))
            .collect::<Vec<_>>()
            .serialize(s)
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<Vec<u8>>, D::Error> {
        Vec::<String>::deserialize(d)?
            .iter()
            .map(|t| decode(t))
            .collect()
    }
}

/// `timestamp` -> RFC 3339 text or `null` (a message field is absent until it is set).
pub mod timestamp {
    use super::*;

    pub fn serialize<S: Serializer>(value: &Option<Timestamp>, s: S) -> Result<S::Ok, S::Error> {
        match value {
            Some(ts) => s.serialize_some(&format_timestamp::<S::Error>(ts)?),
            None => s.serialize_none(),
        }
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Option<Timestamp>, D::Error> {
        Option::<String>::deserialize(d)?
            .map(|t| parse_timestamp(&t))
            .transpose()
    }
}

/// `repeated timestamp` -> a list of RFC 3339 texts.
pub mod timestamp_list {
    use super::*;

    pub fn serialize<S: Serializer>(value: &[Timestamp], s: S) -> Result<S::Ok, S::Error> {
        value
            .iter()
            .map(format_timestamp::<S::Error>)
            .collect::<Result<Vec<_>, _>>()?
            .serialize(s)
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<Timestamp>, D::Error> {
        Vec::<String>::deserialize(d)?
            .iter()
            .map(|t| parse_timestamp(t))
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[derive(Debug, PartialEq, Serialize, Deserialize, Default)]
    #[serde(default)]
    struct Doc {
        #[serde(with = "bytes")]
        data: Vec<u8>,
        #[serde(with = "bytes_opt")]
        maybe: Option<Vec<u8>>,
        #[serde(with = "bytes_list")]
        parts: Vec<Vec<u8>>,
        #[serde(with = "timestamp")]
        at: Option<Timestamp>,
        #[serde(with = "timestamp_list")]
        ats: Vec<Timestamp>,
    }

    #[test]
    fn bytes_are_base64_and_round_trip() {
        let doc = Doc {
            data: vec![0, 1, 2, 250, 251, 255],
            maybe: Some(b"hi".to_vec()),
            parts: vec![b"a".to_vec(), vec![]],
            ..Doc::default()
        };
        let json = serde_json::to_value(&doc).unwrap();
        assert_eq!(json["data"], "AAEC+vv/");
        assert_eq!(json["maybe"], "aGk=");
        assert_eq!(json["parts"], serde_json::json!(["YQ==", ""]));
        assert_eq!(serde_json::from_value::<Doc>(json).unwrap(), doc);
    }

    #[test]
    fn unpadded_base64_is_accepted_and_garbage_is_not() {
        let doc: Doc = serde_json::from_str(r#"{"data":"aGk"}"#).unwrap();
        assert_eq!(doc.data, b"hi");
        assert!(serde_json::from_str::<Doc>(r#"{"data":"not base64!"}"#).is_err());
        assert!(serde_json::from_str::<Doc>(r#"{"data":12}"#).is_err());
    }

    #[test]
    fn timestamps_are_rfc3339_in_utc() {
        let doc = Doc {
            at: Some(Timestamp {
                seconds: 1_794_000_000,
                nanos: 0,
            }),
            ats: vec![Timestamp {
                seconds: 0,
                nanos: 500_000_000,
            }],
            ..Doc::default()
        };
        let json = serde_json::to_value(&doc).unwrap();
        assert_eq!(json["at"], "2026-11-06T21:20:00Z");
        assert_eq!(json["ats"], serde_json::json!(["1970-01-01T00:00:00.500Z"]));
        assert_eq!(serde_json::from_value::<Doc>(json).unwrap(), doc);
    }

    #[test]
    fn any_offset_is_read_and_converted() {
        let doc: Doc = serde_json::from_str(r#"{"at":"2026-11-06T23:20:00+02:00"}"#).unwrap();
        assert_eq!(
            doc.at,
            Some(Timestamp {
                seconds: 1_794_000_000,
                nanos: 0
            })
        );
        assert!(serde_json::from_str::<Doc>(r#"{"at":"yesterday"}"#).is_err());
        assert!(serde_json::from_str::<Doc>(r#"{"at":"2026-11-06"}"#).is_err());
        // Absent and null are both "not set".
        assert_eq!(
            serde_json::from_str::<Doc>(r#"{"at":null}"#).unwrap().at,
            None
        );
        assert_eq!(serde_json::from_str::<Doc>("{}").unwrap().at, None);
    }
}
